	static boolean canFire(int weaponId, String category, String weaponName, int ammoId, String ammoName)
	{
		int[] fires = FIRES.get(weaponId);
		if (fires != null && KNOWN_AMMO.contains(ammoId))
		{
			for (int id : fires)
			{
				if (id == ammoId)
				{
					return true;
				}
