package com.caplanner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;
import net.runelite.client.hiscore.HiscoreSkill;
import org.junit.Test;

public class BossIconsTest
{
	private static List<String> hiscores()
	{
		List<String> names = new ArrayList<>();
		for (HiscoreSkill s : HiscoreSkill.values())
		{
			names.add(s.getName());
		}
		return names;
	}

	@Test
	public void everyBossOfTheAchievementsHasAnIcon() throws Exception
	{
		List<String> hiscores = hiscores();
		TreeSet<String> without = new TreeSet<>();
		TreeSet<String> byItem = new TreeSet<>();
		try (BufferedReader in = new BufferedReader(new InputStreamReader(
			BossIconsTest.class.getResourceAsStream("/com/caplanner/bosses.txt"), StandardCharsets.UTF_8)))
		{
			String boss;
			while ((boss = in.readLine()) != null)
			{
				if (boss.trim().isEmpty() || BossIcons.match(boss, hiscores) != null)
				{
					continue;
				}
				if (BossIcons.item(boss) > 0)
				{
					byItem.add(BossIcons.key(boss));
				}
				else
				{
					without.add(boss);
				}
			}
		}
		assertEquals("bosses with no icon at all", "[]", without.toString());
		// an item only for a boss the hiscores do not have: none left over from a boss they now have
		assertEquals(new TreeSet<>(BossIcons.withItems()).toString(), byItem.toString());
	}

	@Test
	public void namesAreMatchedLoosely()
	{
		List<String> hiscores = hiscores();
		assertEquals("Vardorvis", BossIcons.match("Vardorvis", hiscores));
		assertEquals(BossIcons.match("Leviathan", hiscores), BossIcons.match("The Leviathan", hiscores));
		assertEquals(BossIcons.match("Theatre of Blood", hiscores), BossIcons.match("Theatre of Blood: Entry Mode", hiscores));
		assertNull(BossIcons.match("Bloodveld", hiscores));
		assertNull(BossIcons.match(null, hiscores));
		assertEquals(13496, BossIcons.item("Bloodveld"));
		assertEquals(-1, BossIcons.item("Vardorvis"));
		assertEquals(-1, BossIcons.item(null));
	}
}

package com.caplanner.core;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Development only: a gear card from the JSON the bench writes, for drawing it outside the game. */
public final class CardJson
{
	private static final Map<String, Integer> SLOT = new HashMap<>();

	static
	{
		String[] names = {"head", "cape", "neck", "weapon", "body", "shield", "", "legs", "", "hands", "feet", "", "ring", "ammo"};
		for (int i = 0; i < names.length; i++)
		{
			if (!names[i].isEmpty())
			{
				SLOT.put(names[i], i);
			}
		}
	}

	private CardJson()
	{
	}

	private static Bag.Line line(JsonObject o)
	{
		return new Bag.Line(o.get("id").getAsInt(), o.get("name").getAsString(), o.get("quantity").getAsInt(),
			o.has("slots") && o.get("slots").getAsInt() == 1 && o.get("quantity").getAsInt() > 1, o.get("needed").getAsBoolean(),
			o.get("owned").getAsBoolean(), o.get("why").getAsString());
	}

	private static List<Bag.Line> lines(JsonArray a)
	{
		List<Bag.Line> out = new ArrayList<>();
		for (JsonElement e : a)
		{
			if (!e.isJsonNull())
			{
				out.add(line(e.getAsJsonObject()));
			}
		}
		return out;
	}

	private static String text(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsString() : null;
	}

	public static GearView view(JsonObject c)
	{
		Map<Integer, Integer> ids = new HashMap<>();
		Map<Integer, String> names = new HashMap<>();
		for (Map.Entry<String, JsonElement> e : c.getAsJsonObject("set").entrySet())
		{
			JsonObject piece = e.getValue().getAsJsonObject();
			ids.put(SLOT.get(e.getKey()), piece.get("id").getAsInt());
			names.put(SLOT.get(e.getKey()), piece.get("name").getAsString());
		}
		List<Bag.Line> bag = lines(c.getAsJsonArray("bag"));
		List<String> notes = new ArrayList<>();
		for (JsonElement e : c.getAsJsonArray("notes"))
		{
			notes.add(e.getAsString());
		}
		GearView v = GearView.ready(ids, names, c.get("style").getAsString(), c.get("dps").getAsDouble(),
			c.has("hp") ? c.get("hp").getAsInt() : 0, bag).with(lines(c.getAsJsonArray("worn")), notes);
		List<GearView.Part> parts = new ArrayList<>();
		for (JsonElement e : c.getAsJsonArray("parts"))
		{
			JsonObject p = e.getAsJsonObject();
			GearView.Part part = new GearView.Part(p.get("label").getAsString(), p.get("style").getAsString(), p.get("dps").getAsDouble(),
				lines(p.getAsJsonArray("carried")), text(p, "spell"), p.get("note").getAsString(), p.get("nothing").getAsBoolean(),
				text(p, "sharedWeapon"), text(p, "sharedWith"));
			part.best = text(p, "best");
			parts.add(part);
		}
		if (!parts.isEmpty() || !c.get("wornFor").getAsString().isEmpty())
		{
			v = v.withParts(c.get("wornFor").getAsString(), parts, bag);
		}
		return v;
	}

}

package com.caplanner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

/** Review probes on the kept text of the changes (case 13). */
public class GearChoicesReviewTest
{
	@BeforeClass
	public static void read() throws Exception
	{
		GearEditTest.read();
	}

	@Test
	public void aChangeMadeAfterReadingAnOrderAtTheTopIsStillTheLatest()
	{
		// a text written by hand or damaged: one change whose order is the largest a long holds
		GearChoices read = GearChoices.decode("v1\nVorkath\tworn\t5\t12954\t1\t-1\t" + Long.MAX_VALUE);
		assertEquals("the line is taken, not left out", 1, read.of("Vorkath").size());
		GearChoices now = read.with("Vorkath", GearChoices.WORN, 3, GearEditTest.SCYTHE.itemId, 1, GearChoices.UNKNOWN);
		List<GearChoices.Pin> pins = now.of("Vorkath");
		// on the card, the order decides which of a two-handed weapon and a shield stands
		List<com.caplanner.gear.Gear.Stat> owned = GearEditTest.melee();
		owned.remove(GearEditTest.SCYTHE);
		owned.remove(GearEditTest.MAUL);
		GearView v = GearEditTest.card("Vorkath", -1, owned, now);
		assertEquals("the change just made should be the latest; order " + pins + "; card weapon " + v.itemIdBySlot.get(3) + ", shield "
			+ v.itemIdBySlot.get(5) + ", " + v.changes, 3, pins.get(pins.size() - 1).slot);
	}

	@Test
	public void changesTooManyForTheTextAreNotAllLostAtOnce() throws Exception
	{
		// every slot changed (28 of the inventory, 11 worn) on boss after boss, as the plugin takes them
		GearChoices c = GearChoices.none();
		int made = 0;
		int bosses = 0;
		for (String boss : GearEditTest.bosses())
		{
			for (int slot = 0; slot < 28; slot++)
			{
				c = c.with(boss, GearChoices.BAG, slot, 385, 1, 2434);
				made++;
			}
			for (int s : GearChoices.EQUIPMENT)
			{
				c = c.with(boss, GearChoices.WORN, s, 4151, 1, 4151);
				made++;
			}
			bosses++;
			if (c.encode().length() > GearChoices.MOST_TEXT)
			{
				break;
			}
		}
		int kept = 0;
		for (String boss : c.bosses())
		{
			kept += c.of(boss).size();
		}
		// past the limit a change is refused, never taken and then lost: what is kept is all read back
		assertTrue(kept < made);
		String text = c.encode();
		assertTrue(text.length() <= GearChoices.MOST_TEXT);
		// the next time the plugin reads its settings (CaPlannerPlugin.choices), and so the next change written over them
		assertFalse("the text of " + made + " changes on " + bosses + " bosses (" + text.length() + " characters) reads back as no change at all",
			GearChoices.decode(text).isEmpty());
	}

	@Test
	public void howFarARealAccountIsFromTheLimit() throws Exception
	{
		// informative only (prints): a few changes on every boss
		List<String> all = new ArrayList<>(GearEditTest.bosses());
		for (int each : new int[]{3, 5, 10, 16})
		{
			GearChoices c = GearChoices.none();
			for (String boss : all)
			{
				for (int n = 0; n < each; n++)
				{
					c = n < 11 ? c.with(boss, GearChoices.WORN, new int[]{0, 1, 2, 3, 4, 5, 7, 9, 10, 12, 13}[n], 4151, 1, 4151)
						: c.with(boss, GearChoices.BAG, n - 11, 385, 1, 2434);
				}
			}
			System.out.println("REVIEW-PROBE " + all.size() + " bosses x " + each + " changes: " + c.encode().length() + " of "
				+ GearChoices.MOST_TEXT + " characters");
		}
		assertTrue(all.size() > 0);
	}
}

