		assertTrue(pt.of("Ring: you changed Ultor ring → Lightbearer").endsWith("Ultor ring → Lightbearer"));
		assertTrue(pt.of("Weapon carried for Blue form: you changed Twisted bow → Bow of Faerdhinen (c)").contains("Forma azul"));
	}
}

