/** The provisional inventory of bosses not gone through yet, from the tables the plugin ships. */
public class ProvisionalBagTest
{
	private static BufferedReader reader(String path)
	{
		return new BufferedReader(new InputStreamReader(ProvisionalBagTest.class.getResourceAsStream(path), StandardCharsets.UTF_8));
	}

	private static Bag bag() throws Exception
	{
		Bag bag;
		try (BufferedReader in = reader("/com/caplanner/bag.tsv"))
		{
			bag = Bag.read(in);
		}
		try (BufferedReader in = reader("/com/caplanner/bag-wiki.tsv"))
		{
			bag.readWiki(in);
		}
		return bag;
	}

	private static Map<String, Bag.Have> have(Object... idQuantityName)
	{
		Map<String, Bag.Have> out = new HashMap<>();
		for (int i = 0; i < idQuantityName.length; i += 3)
		{
			String name = (String) idQuantityName[i + 2];
			out.put(name.toLowerCase(Locale.ROOT), new Bag.Have((Integer) idQuantityName[i], (Integer) idQuantityName[i + 1], name));
		}
		return out;
	}

	private static int count(List<Bag.Line> lines, String startOfName)
	{
		int n = 0;
		for (Bag.Line l : lines)
		{
			if (l.name.startsWith(startOfName))
			{
				n += l.quantity;
			}
		}
		return n;
	}

	private static Bag.Provisional of(Bag bag, String boss, String style, Map<String, Bag.Have> have)
	{
		return bag.provisional(boss, style, have, new HashSet<String>(), new HashSet<Integer>(), Bag.SLOTS);
	}

	@Test
	public void theAmountsAreTheWikisAndTheItemsAreThePlayers() throws Exception
	{
		Bag bag = bag();
		Map<String, Bag.Have> owned = have(3024, 100, "Super restore(4)", 6685, 100, "Saradomin brew(4)", 385, 100, "Shark",
			12695, 10, "Super combat potion(4)", 2444, 10, "Ranging potion(4)", 11942, 3, "Ecumenical key", 8013, 5, "Teleport to house");
		Bag.Provisional p = of(bag, "Commander Zilyana", "Ranged", owned);
		assertNotNull(p);
		assertEquals(16, count(p.lines, "Super restore"));
		assertEquals(1, count(p.lines, "Saradomin brew"));
		assertEquals(4, count(p.lines, "Shark"));
		// the potion of the style of the set, not the one of another style
		assertEquals(1, count(p.lines, "Ranging potion"));
		assertEquals(0, count(p.lines, "Super combat"));
		assertEquals(1, count(p.lines, "Ecumenical key"));
		assertTrue(p.lacking.isEmpty());
		// the wiki carries a staff and a shield to change into: said, and not worked out
		assertFalse(p.switches.isEmpty());
		// a piece the set already wears is not a piece to change into
		Set<String> on = new HashSet<>();
		on.add("eldritch nightmare staff");
		assertFalse(p.without(on).switches.contains("Eldritch nightmare staff"));
		assertTrue(p.without(on).switches.contains("Elidinis' ward (f)"));
		on.clear();
		on.add("eldritch nightmare staff (or)");
		assertFalse(p.without(on).switches.contains("Eldritch nightmare staff"));
		// what the fight needs, owned in another dress, is owned
		Bag.Provisional graardor = of(bag, "General Graardor", "Melee", have(99001, 1, "Hammer (or)", 385, 100, "Shark"));
		assertEquals("Hammer (or)", graardor.lines.get(0).name);
		assertTrue(graardor.lines.get(0).owned);
		int slots = 0;
		for (Bag.Line l : p.lines)
		{
			slots += l.slots();
		}
		assertTrue(slots <= Bag.SLOTS);
	}

	@Test
	public void aSpecialItemNotOwnedIsSaidAndNotPutIn() throws Exception
	{
		Bag bag = bag();
		Bag.Provisional p = of(bag, "Commander Zilyana", "Ranged", have(385, 100, "Shark"));
		assertEquals(0, count(p.lines, "Ecumenical key"));
		assertTrue(p.lacking.contains("Ecumenical key"));
		// nothing the player does not own is made up
		assertEquals(0, count(p.lines, "Super restore"));
		assertEquals(4, count(p.lines, "Shark"));
	}

	@Test
	public void whatTheFightNeedsComesFirstAndIsNotTakenTwice() throws Exception
	{
		Bag bag = bag();
		// the gong at Graardor's door: listed though not owned
		Bag.Provisional graardor = of(bag, "General Graardor", "Melee", have(385, 100, "Shark"));
		assertEquals("Hammer", graardor.lines.get(0).name);
		assertTrue(graardor.lines.get(0).needed);
		assertFalse(graardor.lines.get(0).owned);
		// the antifire the dragon's own line takes is not taken again as a kind
		Bag.Provisional dragon = of(bag, "Brutal Black Dragon", "Ranged",
			have(22209, 10, "Extended super antifire(4)", 2452, 10, "Antifire potion(4)", 385, 100, "Shark"));
		assertEquals(1, count(dragon.lines, "Extended super antifire"));
		assertEquals(0, count(dragon.lines, "Antifire potion"));
	}

	@Test
	public void aStackTakesOneSlot() throws Exception
	{
		Bag bag = bag();
		Bag.Provisional p = of(bag, "Lizardman Shaman", "Ranged", have(2, 5000, "Cannonball", 6, 1, "Cannon base"));
		Bag.Line balls = null;
		for (Bag.Line l : p.lines)
		{
			if ("Cannonball".equals(l.name))
			{
				balls = l;
			}
		}
		assertNotNull(balls);
		assertEquals(2000, balls.quantity);
		assertEquals(1, balls.slots());
		assertTrue(p.lacking.contains("Cannon stand"));
		assertFalse(p.lacking.contains("Cannon base"));
		// a cannon with an ornament on it, and cannonballs of another metal, are a cannon and cannonballs
		Bag.Provisional or = of(bag, "Lizardman Shaman", "Ranged", have(31906, 6096, "Steel cannonball", 31900, 12553, "Granite cannonball", 31916, 261, "Rune cannonball",
			26520, 1, "Cannon base (or)", 26522, 1, "Cannon stand (or)", 26524, 1, "Cannon barrels (or)", 26526, 1, "Cannon furnace (or)"));
		assertTrue(or.lacking.toString(), or.lacking.isEmpty());
		assertEquals(2000, count(or.lines, "Granite cannonball"));
		assertEquals(0, count(or.lines, "Steel cannonball"));
		// the other metals are for the cannon of a boat, not for this one
		assertEquals(0, count(or.lines, "Rune cannonball"));
		assertEquals(1, count(or.lines, "Cannon base (or)"));
	}

	@Test
	public void onlyForBossesNotGoneThroughAndInTheTable() throws Exception
	{
		Bag bag = bag();
		Set<String> gone = new HashSet<>();
		for (String boss : new String[]{"Vorkath", "Zulrah", "Dagannoth Rex", "Sarachnis"})
		{
			assertTrue(boss, bag.isMapped(boss));
			assertFalse(boss, bag.isProvisional(boss));
			assertNull(boss, of(bag, boss, "Ranged", have(385, 100, "Shark")));
			gone.add(boss);
		}
		// a boss in neither table has none
		assertFalse(bag.isProvisional("Crystalline Hunllef"));
		assertNull(of(bag, "Crystalline Hunllef", "Ranged", have(385, 100, "Shark")));
		assertTrue(bag.isProvisional("Nex"));
	}

	/** What the audit of October 2026 found in the wiki's inventories (each boss's Strategies page). */
	@Test
	public void theAuditedInventoriesAreTheWikis() throws Exception
	{
		Bag bag = bag();
		// Deranged archaeologist: a Forgotten brew (a Magic boost), not a Saradomin brew, and an axe for the swamp vine
		Bag.Provisional deranged = of(bag, "Deranged Archaeologist", "Magic", have(6685, 10, "Saradomin brew(4)",
			27629, 5, "Forgotten brew(4)", 1359, 1, "Rune axe", 385, 100, "Shark"));
		assertEquals(1, count(deranged.lines, "Forgotten brew"));
		assertEquals(0, count(deranged.lines, "Saradomin brew"));
		assertEquals(1, count(deranged.lines, "Rune axe"));
		Bag.Provisional noAxe = of(bag, "Deranged Archaeologist", "Magic", have(385, 100, "Shark"));
		assertTrue(noAxe.lacking.contains("Axe"));
		assertTrue("a pickaxe is not an axe", of(bag, "Deranged Archaeologist", "Magic",
			have(11920, 1, "Dragon pickaxe", 385, 100, "Shark")).lacking.contains("Axe"));
		// Nex: 13 Saradomin brews and 3 Armadyl brews
		Bag.Provisional nex = of(bag, "Nex", "Ranged", have(6685, 30, "Saradomin brew(4)", 22461, 10, "Armadyl brew(4)",
			3024, 30, "Super restore(4)"));
		assertEquals(13, count(nex.lines, "Saradomin brew"));
		assertEquals(3, count(nex.lines, "Armadyl brew"));
		// Scorpia: a cure for her poison and a Lockpick
		Bag.Provisional scorpia = of(bag, "Scorpia", "Ranged", have(12913, 5, "Anti-venom+(4)", 1523, 1, "Lockpick",
			385, 100, "Shark"));
		assertEquals(2, count(scorpia.lines, "Anti-venom+"));
		assertEquals(1, count(scorpia.lines, "Lockpick"));
		// General Graardor: the wiki's inventory has no Ecumenical key, so none is said to be missing
		assertFalse(of(bag, "General Graardor", "Melee", have(385, 100, "Shark")).lacking.contains("Ecumenical key"));
	}
}

package com.caplanner.core;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.BeforeClass;
import org.junit.Test;

/** Case 20: a report of a card the player changed says so, with the changes, and the set the planner recommended. */
public class ReportEditTest
{
	@BeforeClass
	public static void read() throws Exception
	{
		GearEditTest.read();
	}

	@Test
	public void aReportOfAChangedCardSaysItWasChangedAndHow()
	{
		GearView rec = GearEditTest.card("Vorkath", -1, GearEditTest.melee(), null);
		GearView v = GearEditTest.card("Vorkath", -1, GearEditTest.melee(),
			GearChoices.none().with("Vorkath", GearChoices.WORN, 12, 25975, 1, 11773));
		String report = Report.body("Vorkath", null, "x", v, null, "", "English");
		assertTrue(report, report.contains("- gear edited by the player"));
		assertTrue(report, report.contains("- change: Ring: you changed Berserker ring (i) → Lightbearer"));
		assertTrue(report, report.contains("ring Lightbearer"));
		assertTrue(report, report.contains("- recommended set: ") && report.contains("ring Berserker ring (i)"));
		String plain = Report.body("Vorkath", null, "x", rec, null, "", "English");
		assertFalse(plain.contains("edited by the player"));
	}
}

package com.caplanner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.net.URLDecoder;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class ReportTest
{
	private static final Task TASK = new Task(272, "Dodging the Dragon", "Kill Vorkath 5 times without taking any damage.",
		Tier.MASTER, TaskType.PERFECTION, "Vorkath");

	private static GearView view()
	{
		Map<Integer, Integer> ids = new HashMap<>();
		Map<Integer, String> names = new HashMap<>();
		ids.put(3, 22978);
		names.put(3, "Dragon hunter lance");
		ids.put(5, 22322);
		names.put(5, "Avernic defender");
		List<Bag.Line> carried = Arrays.asList(Bag.Line.worn(20997, "Twisted bow", true, ""));
		List<Bag.Line> bag = new ArrayList<>();
		bag.add(Bag.Line.worn(4162, "Rock hammer", false, "to finish it off"));
		return GearView.ready(ids, names, "Melee", 10.784, 750, bag)
			.withParts("The dragon", Arrays.asList(new GearView.Part("Spawn", "Ranged", 5.5, carried, null, "", false)), bag);
	}

	@Test
	public void theReportSaysWhatThePlayerWroteAndWhatThePlannerGave()
	{
		List<String> why = new ArrayList<>();
		why.add("Finish Dragon Slayer II");
		String body = Report.body("Vorkath", TASK, "  It says I cannot, but I have done the quest.  ", view(), Verdict.blocked(why),
			"Attack 99, Slayer 90; Slayer task: none", "Portuguese");
		assertTrue(body.contains("It says I cannot, but I have done the quest."));
		assertTrue(body.contains("**Boss:** Vorkath"));
		assertTrue(body.contains("Dodging the Dragon (id 272, Master, Perfection)"));
		assertTrue(body.contains("Kill Vorkath 5 times without taking any damage."));
		assertTrue(body.contains("BLOCKED (Finish Dragon Slayer II)"));
		assertTrue(body.contains("weapon Dragon hunter lance | shield Avernic defender"));
		assertTrue(body.contains("Melee, 10.78 dps, boss hitpoints 750"));
		assertTrue(body.contains("worn for: The dragon"));
		assertTrue(body.contains("part \"Spawn\": Ranged, 5.5 dps -> Twisted bow"));
		assertTrue(body.contains("1 x Rock hammer (needed, not owned)"));
		assertTrue(body.contains("Attack 99, Slayer 90; Slayer task: none"));
		assertTrue(body.contains("**Panel language:** Portuguese"));
		// a boss alone, with nothing shown and nothing written, is still a report
		String bare = Report.body("Zulrah", null, "", null, null, "", null);
		assertTrue(bare.contains("(nothing written)") && bare.contains("nothing shown yet") && bare.contains("not known"));
		assertFalse(bare.contains("**Task:**"));
	}

	@Test
	public void theTitleNamesTheBossAndTheTaskAndTheLinkCarriesTheReport() throws Exception
	{
		assertEquals("[Vorkath] Dodging the Dragon: It says I cannot", Report.title("Vorkath", TASK, " It says\n I cannot "));
		assertEquals("[Zulrah]", Report.title("Zulrah", null, ""));
		String longWords = new String(new char[30]).replace("\0", "word ");
		assertTrue(Report.title("Zulrah", null, longWords).endsWith("..."));
		String link = Report.link("[Vorkath] a & b", "line one\nline two: 100%");
		assertTrue(link.startsWith("https://github.com/GuimGod/ca-planner/issues/new?title="));
		assertFalse("a space must not be a plus, which the site keeps as a plus", link.contains("+"));
		String query = link.substring(link.indexOf('?') + 1);
		assertEquals("[Vorkath] a & b", URLDecoder.decode(query.substring(6, query.indexOf("&body=")), "UTF-8"));
		assertEquals("line one\nline two: 100%", URLDecoder.decode(query.substring(query.indexOf("&body=") + 6), "UTF-8"));
		// a report too long for a link is cut at a line and says so
		StringBuilder big = new StringBuilder();
		for (int i = 0; i < 400; i++)
		{
			big.append("- a line of the report number ").append(i).append('\n');
		}
		String cut = URLDecoder.decode(Report.link("t", big.toString()), "UTF-8");
		assertTrue(cut.length() < 6200);
		assertTrue(cut.endsWith("(Cut short to fit in a link. Paste the copied report here for the rest.)"));
	}
}

package com.caplanner.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

/** The cases a review of the first version found. */
public class RequirementsEdgeTest
{
	private static final Task KRAKEN = new Task(1, "Krakan't Hurt Me", "Kill the Kraken.", Tier.HARD, TaskType.KILL_COUNT, "Kraken");

	private static Requirements table(String lines) throws Exception
	{
		return Requirements.read(new StringReader(lines));
	}

	private static Account onTask(String task)
	{
		Account a = new Account();
		a.levels.put("slayer", 99);
		a.slayerTask = task;
		return a;
	}

	@Test
	public void theBossesTaskAndAnUnreadableTaskDoNotHideABoss() throws Exception
	{
		Requirements r = table("Kraken\t\tSlayer 87\tCave kraken; Kraken\n");
		assertFalse("no task at all", r.check(KRAKEN, onTask(null)).can());
		assertFalse(r.check(KRAKEN, onTask("Hellhounds")).can());
		assertTrue(r.check(KRAKEN, onTask("CAVE KRAKEN")).can());
		assertTrue("the other name the game may use", r.check(KRAKEN, onTask("Kraken")).can());
		assertTrue("a boss task: which boss is not read, so it is not hidden", r.check(KRAKEN, onTask("Bosses")).can());
		Account unknown = onTask(null);
		unknown.slayerTaskUnknown = true;
		assertTrue("a task whose name could not be read", r.check(KRAKEN, unknown).can());
		// the level still counts on task
		Account low = onTask("Cave kraken");
		low.levels.put("slayer", 86);
		assertEquals("Slayer 87 (you have 86)", r.check(KRAKEN, low).reasons.get(0));
	}

	@Test
	public void aBadCellLosesOnlyItself() throws Exception
	{
		Requirements r = table("Kraken\tRegicide*\tSlayer87; Agility x; Slayer 87\t\n# a comment\n\nMole\n");
		Account a = new Account();
		a.levels.put("slayer", 50);
		assertEquals(2, r.check(KRAKEN, a).reasons.size());
		assertEquals("Start Regicide", r.check(KRAKEN, a).reasons.get(0));
		assertEquals("Slayer 87 (you have 50)", r.check(KRAKEN, a).reasons.get(1));
		// a line with only a boss name is a boss that needs nothing
		assertTrue(r.check(new Task(2, "x", "Kill the mole.", Tier.EASY, TaskType.KILL_COUNT, "Mole"), new Account()).can());
	}

	@Test
	public void wordingAboutPlayersIsReadTheRightWay()
	{
		assertFalse("an upper limit is met alone", group("Nex Trio", "Kill Nex with three or less players at the start of the fight."));
		assertFalse(group("Nex Duo", "Kill Nex with two or less players at the start of the fight."));
		assertFalse(group("Hueycoatl Speed-Runner", "Kill the Hueycoatl in 2:30 with three or fewer players."));
		assertFalse(group("Tombs Speed Runner", "Complete the Tombs of Amascut (normal) within 18 mins at any group size."));
		assertFalse(group("Chicken Killer", "Kill the Corporeal Beast solo."));
		assertTrue(group("Theatre (Trio) Speed-Chaser", "Complete the Theatre of Blood (Trio) in less than 20 minutes."));
		assertTrue(group("Nightmare (5-Scale) Speed-Chaser", "Defeat the Nightmare (5-scale) in less than 4 minutes."));
		assertTrue(group("Personal Space", "Defeat the Pestilent Bloat with at least 3 people in the room."));
		assertTrue(group("Pass It On", "Successfully pass on the green ball to a team mate."));
		assertTrue(group("Perfect Akkha", "Complete Akkha in a group of two or more, without anyone taking damage."));
	}

	@Test
	public void oneLevelOfTwoIsEnough() throws Exception
	{
		Requirements r = table("K'ril Tsutsaroth\t\tHitpoints 70; Strength 60 or Agility 60\t\n");
		Task kril = new Task(3, "x", "Kill K'ril.", Tier.HARD, TaskType.KILL_COUNT, "K'ril Tsutsaroth");
		Account a = new Account();
		a.levels.put("hitpoints", 70);
		a.levels.put("strength", 50);
		a.levels.put("agility", 40);
		assertEquals("Strength 60 (you have 50) or Agility 60 (you have 40)", r.check(kril, a).reasons.get(0));
		assertEquals(1, r.check(kril, a).reasons.size());
		a.levels.put("agility", 60);
		assertTrue("Agility alone does", r.check(kril, a).can());
		a.levels.put("agility", 40);
		a.levels.put("strength", 60);
		assertTrue("Strength alone does", r.check(kril, a).can());
	}

	@Test
	public void aLineForOneTaskAddsToItsBoss() throws Exception
	{
		Requirements r = table("Ket-Rak\tTzHaar\t\t\t\nKet-Rak#362\t\t\t\tinferno-done=Complete the Inferno once\nKet-Rak#x\tNot a quest\n");
		Task first = new Task(361, "x", "First challenge.", Tier.ELITE, TaskType.KILL_COUNT, "Ket-Rak");
		Task third = new Task(362, "x", "Fourth challenge.", Tier.ELITE, TaskType.KILL_COUNT, "Ket-Rak");
		Account a = new Account();
		a.quests.put("tzhaar", Account.QuestProgress.FINISHED);
		assertTrue("the task with no line of its own needs only its boss's", r.check(first, a).can());
		assertEquals("Complete the Inferno once", r.check(third, a).reasons.get(0));
		a.done.add("inferno-done");
		assertTrue(r.check(third, a).can());
		// the boss's own needs still count for the task with a line of its own
		a.quests.clear();
		assertEquals("Finish TzHaar", r.check(third, a).reasons.get(0));
		assertFalse("a line with no task id is left out", r.questNames().contains("Not a quest"));
	}

	/** The audit of October 2026: what the bundled table was missing. */
	@Test
	public void theBundledTableAsksForWhatTheWikiDoes() throws Exception
	{
		Requirements r;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(
			RequirementsEdgeTest.class.getResourceAsStream("/com/caplanner/requirements.tsv"), StandardCharsets.UTF_8)))
		{
			r = Requirements.read(in);
		}
		// TzHaar-Ket-Rak: the third challenge on asks for the Inferno; the first two do not
		Account a = new Account();
		for (int id : new int[]{361, 364, 367})
		{
			assertTrue("task " + id, r.check(new Task(id, "x", "x", Tier.ELITE, TaskType.KILL_COUNT, "TzHaar-Ket-Rak's Challenges"), a).can());
		}
		for (int id : new int[]{362, 363, 365, 366, 368, 369, 370, 371})
		{
			Task t = new Task(id, "x", "x", Tier.ELITE, TaskType.KILL_COUNT, "TzHaar-Ket-Rak's Challenges");
			assertEquals("task " + id, "Complete the Inferno once", r.check(t, a).reasons.get(0));
		}
		a.done.add("inferno-done");
		assertTrue(r.check(new Task(371, "x", "x", Tier.ELITE, TaskType.KILL_COUNT, "TzHaar-Ket-Rak's Challenges"), a).can());
		// the Grotesque Guardians' rooftop and the Abyss, on the boss's Slayer task
		Account slayer = onTask("Gargoyles");
		assertFalse(r.check(new Task(1, "x", "x", Tier.HARD, TaskType.KILL_COUNT, "Grotesque Guardians"), slayer).can());
		slayer.done.add("gg-roof");
		assertTrue(r.check(new Task(1, "x", "x", Tier.HARD, TaskType.KILL_COUNT, "Grotesque Guardians"), slayer).can());
		Account abyss = onTask("Abyssal demons");
		assertFalse(r.check(new Task(1, "x", "x", Tier.HARD, TaskType.KILL_COUNT, "Abyssal Sire"), abyss).can());
		abyss.done.add("abyss-access");
		assertTrue(r.check(new Task(1, "x", "x", Tier.HARD, TaskType.KILL_COUNT, "Abyssal Sire"), abyss).can());
		// K'ril and Kree'arra: into the God Wars Dungeon with Strength 60 or Agility 60
		Account gwd = new Account();
		gwd.quests.put(Requirements.key("Troll Stronghold"), Account.QuestProgress.FINISHED);
		gwd.levels.put("hitpoints", 70);
		gwd.levels.put("ranged", 70);
		gwd.levels.put("strength", 59);
		gwd.levels.put("agility", 59);
		assertFalse(r.check(new Task(1, "x", "x", Tier.HARD, TaskType.KILL_COUNT, "K'ril Tsutsaroth"), gwd).can());
		assertFalse(r.check(new Task(1, "x", "x", Tier.HARD, TaskType.KILL_COUNT, "Kree'arra"), gwd).can());
		gwd.levels.put("agility", 60);
		assertTrue(r.check(new Task(1, "x", "x", Tier.HARD, TaskType.KILL_COUNT, "K'ril Tsutsaroth"), gwd).can());
		assertTrue(r.check(new Task(1, "x", "x", Tier.HARD, TaskType.KILL_COUNT, "Kree'arra"), gwd).can());
		// and each new reason is said in Portuguese
		Lang pt;
		try (BufferedReader in = new BufferedReader(new InputStreamReader(
			RequirementsEdgeTest.class.getResourceAsStream("/com/caplanner/lang/pt.tsv"), StandardCharsets.UTF_8)))
		{
			pt = Lang.read(in);
		}
		assertEquals("Strength 60 (você tem 50) ou Agility 60 (você tem 40)",
			pt.of("Strength 60 (you have 50) or Agility 60 (you have 40)"));
		assertEquals("Complete o Inferno uma vez", pt.of("Complete the Inferno once"));
		assertTrue(pt.of("Unlock the rooftop with a brittle key, from gargoyles on a Slayer task").startsWith("Destranque"));
		assertTrue(pt.of("Reach the Abyss once: the Enter the Abyss miniquest, or the fairy rings").startsWith("Chegue"));
	}

	private static boolean group(String name, String description)
	{
		return Requirements.needsGroup(new Task(1, name, description, Tier.MASTER, TaskType.SPEED, "x"));
	}
}

package com.caplanner.core;

import static org.junit.Assert.assertTrue;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Test;

/** The bundled table must only name quests, skills and bosses that exist, or a requirement would never be met. */
public class RequirementsTableTest
{
	@Test
	public void everyNameInTheTableExists() throws Exception
	{
		Set<String> quests = new HashSet<>();
		for (Quest q : Quest.values())
		{
			quests.add(Requirements.key(q.getName()));
		}
		Set<String> skills = new HashSet<>();
		for (Skill s : Skill.values())
		{
			skills.add(s.getName().toLowerCase());
		}
		Set<String> bosses = new HashSet<>();
		try (BufferedReader in = reader("/com/caplanner/bosses.txt"))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				bosses.add(Requirements.key(line));
			}
		}
		try (BufferedReader in = reader("/com/caplanner/requirements.tsv"))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				if (line.trim().isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] cols = line.split("\t", -1);
				// "boss#task id": what one task of the boss needs on top of the boss's own
				String boss = cols[0].contains("#") ? cols[0].substring(0, cols[0].indexOf('#')) : cols[0];
				if (cols[0].contains("#"))
				{
					assertTrue("not a task id: " + cols[0], cols[0].substring(cols[0].indexOf('#') + 1).matches("\\d+"));
				}
				assertTrue("boss not in the Combat Achievements: " + cols[0], bosses.contains(Requirements.key(boss)));
				for (String quest : cols[1].split(";"))
				{
					String name = quest.replace("*", "").trim();
					assertTrue("quest the client does not know: " + name, name.isEmpty() || quests.contains(Requirements.key(name)));
				}
				for (String levels : cols[2].split(";"))
				{
					// "Skill N or Skill N": one of them is enough
					for (String level : levels.split(" or "))
					{
						if (!level.trim().isEmpty())
						{
							String skill = level.trim().substring(0, level.trim().lastIndexOf(' ')).toLowerCase();
							assertTrue("skill the client does not know: " + skill, skills.contains(skill));
						}
					}
				}
			}
		}
	}

	private static BufferedReader reader(String resource)
	{
		return new BufferedReader(new InputStreamReader(
			RequirementsTableTest.class.getResourceAsStream(resource), StandardCharsets.UTF_8));
	}
}

