		p.strength = 118;
		p.ranged = 112;
		for (int id : new int[]{12596, 14147})
		{
			SetCalc.Target t = data.monster(id).target();
			assertEquals(-1, SetCalc.perTick(tbow, p, t, false), 0);
			assertTrue(SetCalc.perTick(fang, p, t, false) > 0);
