	}

	/**
	 * The Tormented Demon, every id: its fire shield takes a fifth off each hit (at least 1) of anything but a
	 * demonbane weapon or an abyssal weapon in melee, and half of the attacks are counted as meeting it without defence,
	 * every one of them landing, in every class (the plugin does not read yet which it is,
	 * until it does). The calculator has no such phase: each case is the mean, style by style, of its phases
	 * "Shielded" and "Shielded (Defenceless)" (tools/gen_rules.py). The Emberlight over the Scythe and the Scorching bow
	 * over the Twisted bow, where the plugin asked for the other two before; the abyssal weapons take no shield.
	 */
	@Test
	public void theTormentedDemonsShieldAndHalfItsAttacksWithoutDefence() throws IOException
	{
		for (int id = 13599; id <= 13602; id++)
		{
			Map<String, SetCalcTest.Case> demon = on(id, 0);
			assertEquals(17, demon.size());
			for (SetCalcTest.Case k : demon.values())
			{
				assertEquals(k.set + " on " + id, k.expected, k.got, 0.001 * k.expected);
			}
			first(demon, "emberlight", "scythe");
			first(demon, "scorching", "tbow");
			first(demon, "tentacle", "rapier");
			first(demon, "abyssal-dagger", "scythe");
		}
		StyleData data = new StyleData();
		SetCalc.Target demon = data.monster(13599).target();
		assertTrue(demon.fireShield);
		assertEquals(0.5, demon.defencelessShare, 0);
		assertEquals(0.5, Weapons.defencelessShare("Tormented Demon"), 0);
		assertEquals(0, data.monster(415).target().defencelessShare, 0);
		// half of the attacks land without a roll: (chance + 1) / 2
		assertEquals(0.7, SetCalc.withDefenceless(demon, 0.4), 1e-12);
		SetCalc.Player p = new SetCalc.Player();
		SetCalc.Loadout scythe = new SetCalc.Loadout();
		scythe.weaponName = "Scythe of vitur";
		scythe.category = "Scythe";
		assertEquals(4, SetCalc.hitScale(scythe, p, demon, StyleCalc.MELEE).numerator);
		assertEquals(5, SetCalc.hitScale(scythe, p, demon, StyleCalc.MELEE).divisor);
		SetCalc.Loadout ember = new SetCalc.Loadout();
		ember.weaponName = "Emberlight";
		ember.category = "Slash Sword";
		assertEquals(1, SetCalc.hitScale(ember, p, demon, StyleCalc.MELEE).divisor);
		SetCalc.Loadout whip = new SetCalc.Loadout();
		whip.weaponName = "Abyssal whip";
		whip.category = "Whip";
		assertEquals(1, SetCalc.hitScale(whip, p, demon, StyleCalc.MELEE).divisor);
		// a hit of 1 stays 1 under the shield, 3 becomes 2
		assertEquals(1, SetCalc.landed(1, 1, demon, SetCalc.FIRE_SHIELD), 1e-12);
		assertEquals(2, SetCalc.landed(3, 3, demon, SetCalc.FIRE_SHIELD), 1e-12);
	}

	/** Every case of a monster within 0.1% of the calculator; the cases, by set. */
	private static Map<String, SetCalcTest.Case> calculators(int npc) throws IOException
	{
		Map<String, SetCalcTest.Case> cases = on(npc, 0);
		assertTrue("cases on " + npc, cases.size() >= 10);
		for (SetCalcTest.Case k : cases.values())
		{
			assertEquals(k.set + " on " + npc, k.expected, k.got, 0.001 * k.expected);
		}
		return cases;
	}

	/**
	 * Araxxor's Acidic and Mirrorback araxytes (by the name, as the calculator has it): every attack lands at the max
	 * hit with the Noxious halberd, with a crush style while crush is the highest attack bonus worn, and with a crossbow
	 * while ranged is (OSRS Wiki: "always max hit ... crush or heavy Ranged weapon ... or the noxious halberd"). The
	 * Inquisitor's mace and the halberd over the blowpipe, which the plugin asked for before; a crossbow in melee armour,
	 * where ranged is not the highest bonus, is counted as usual.
	 */
	@Test
	public void theAraxytesTakeTheMaxHitFromCrushCrossbowsAndTheHalberd() throws IOException
	{
		for (int id : new int[]{13675, 13671})
		{
			Map<String, SetCalcTest.Case> araxyte = calculators(id);
			first(araxyte, "inquisitors-mace", "blowpipe");
			first(araxyte, "noxious-halberd", "blowpipe");
			first(araxyte, "noxious-halberd", "scythe");
			first(araxyte, "zcb-runite", "tbow");
			first(araxyte, "zcb-runite", "zcb-in-melee-armour");
		}
		assertEquals("crush", SetCalc.highestBonus(129, 72, 215, -48, -55));
		assertEquals("ranged", SetCalc.highestBonus(-15, -16, -15, 273, -29));
		// a tie is the earlier of slash, stab, crush, ranged, magic (the calculator's order)
		assertEquals("slash", SetCalc.highestBonus(50, 50, 50, 50, 50));
		assertEquals("slash", SetCalc.highestBonus(40, 77, 40, 65, -65));
		// the attack style: with crush the highest bonus, every crush attack is a max hit, and Pound is the style
		StyleData data = new StyleData();
		StyleData.Monster acidic = data.monster(13675);
		StyleCalc.Input in = new StyleCalc.Input();
		in.attackLevel = 118;
		in.strengthLevel = 118;
		in.prayerAttack = 120;
		in.prayerStrength = 123;
		in.stab = 129;
		in.slash = 72;
		in.crush = 215;
		in.ranged = -48;
		in.magic = -55;
		in.strength = 166;
		in.defenceLevel = acidic.level;
		in.defenceStab = acidic.stab;
		in.defenceSlash = acidic.slash;
		in.defenceCrush = acidic.crush;
		in.araxyteMax = Weapons.araxyteMax(acidic.name);
		double crush = StyleCalc.expectedHit(in, StyleCalc.CRUSH, "Aggressive");
		assertEquals(StyleCalc.chanceAndMax(in, StyleCalc.CRUSH, "Aggressive")[1], crush, 0);
		assertTrue(crush > StyleCalc.expectedHit(in, StyleCalc.STAB, "Aggressive"));
		in.araxyteMax = false;
		assertTrue(StyleCalc.expectedHit(in, StyleCalc.CRUSH, "Aggressive") < crush);
	}

	/**
	 * The Ruptura araxyte takes the max hit as the Acidic and the Mirrorback do: the OSRS Wiki has the same sentence on the
	 * three pages ("Players will always max hit when attacking them with a crush or heavy Ranged weapon ... or the noxious
	 * halberd"), while the calculator has the rule for the two others only (PlayerVsNPCCalc.ts, by the name). The wiki
	 * decides the mechanics: with the Acidic's levels, bonuses and size, every one of the Acidic's cases
	 * on the Ruptura is the calculator's figure for the Acidic, within 0.1%.
	 */
	@Test
	public void theRupturaAraxyteTakesTheMaxHitToo() throws IOException
	{
		assertTrue(Weapons.araxyteMax("Ruptura Araxyte"));
		assertTrue(new StyleData().monster(13673).target().araxyteMax);
		int n = 0;
		for (SetCalcTest.Case k : SetCalcTest.cases("rules_sets.tsv", npc -> npc == 13675 ? 13673 : npc))
		{
			if (k.npc == 13673)
			{
				assertEquals(k.set + " on the Ruptura", k.expected, k.got, 0.001 * k.expected);
				n++;
			}
		}
		assertTrue("cases", n >= 10);
	}

	/**
	 * Every attack lands on the Spawn of the Abyssal Sire, in every class (the calculator's GUARANTEED_ACCURACY_MONSTERS),
	 * on both of the ids the OSRS Wiki gives it (the calculator lists the first).
	 */
	@Test
	public void everyAttackLandsOnTheSpawn() throws IOException
	{
		StyleData data = new StyleData();
		for (int id : new int[]{5916, 5917})
		{
			calculators(id);
			assertTrue(data.monster(id).everyAttackLands);
		}
	}

	/**
	 * Scurrius's Giant rats and the Flowers of Hespori and of A Night at the Theatre die in one hit from any attack (the
	 * calculator's ONE_HIT_MONSTERS; OSRS Wiki: "always die in one hit"): every attack deals their hitpoints, so the
	 * faster weapon is the better one: the rapier over the Scythe, the blowpipe over both.
	 */
	@Test
	public void theRatsAndTheFlowersDieInOneHit() throws IOException
	{
		StyleData data = new StyleData();
		for (int id : new int[]{7223, 8584, 11193})
		{
			Map<String, SetCalcTest.Case> one = calculators(id);
			first(one, "rapier", "scythe");
			first(one, "blowpipe", "rapier");
			assertTrue(data.monster(id).oneHit);
		}
		assertTrue(!data.monster(415).oneHit);
		// every attack style ties there: no style is ever pointed at
		StyleCalc.Input in = new StyleCalc.Input();
		in.attackLevel = 118;
		in.strengthLevel = 118;
		in.stab = 100;
		in.slash = 50;
		in.strength = 90;
		in.oneHit = true;
		assertEquals(StyleCalc.expectedHit(in, StyleCalc.STAB, "Accurate"), StyleCalc.expectedHit(in, StyleCalc.SLASH, "Aggressive"), 0);
		assertTrue(StyleCalc.expectedHit(in, StyleCalc.STAB, "Accurate") > 0);
	}

	/** The Hueycoatl's head in each of its ids (14009, 14010, 14013) is the head, not the body found by the name. */
	@Test
	public void theHueycoatlsHeadInEachId() throws IOException
	{
		StyleData data = new StyleData();
		for (int id : new int[]{14009, 14010, 14013})
		{
			assertEquals(7, data.monster(id).size);
			assertEquals(2500, data.monster(id).hitpoints);
		}
		assertEquals(1, data.monster(14017).size);
		assertTrue(on(14013, 0).get("scythe").got > 0);
	}
}

package com.caplanner.gear;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.caplanner.core.GearCard;
import com.caplanner.core.Rules;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import org.junit.Test;

/**
 * The parts carried by name against every task of the Combat Achievements: none takes a weapon the task's rule does not
 * allow or an item it excludes, and no special attack that lowers Defence is listed for a boss that takes none.
 */
public class FightTaskRulesTest
{
	/** Special attacks that lower the target's Defence. */
	private static final List<String> DRAINS = Arrays.asList("elder maul", "dragon warhammer", "bandos godsword", "arclight",
		"emberlight", "bone dagger", "soulflame horn", "barrelchest anchor", "seercull", "accursed sceptre", "eye of ayak",
		"tonalztics of ralos", "dorgeshuun crossbow");
	/** Bosses whose Defence cannot be lowered, in one of their fights at least (DefenceDrains, the awakened fights, the Moons). */
	private static final List<String> UNDRAINED = Arrays.asList("Moons of Peril", "Brutus", "Vardorvis", "Duke Sucellus", "Leviathan",
		"Whisperer");

	private static BufferedReader reader(String resource)
	{
		return new BufferedReader(new InputStreamReader(FightTaskRulesTest.class.getResourceAsStream(resource), StandardCharsets.UTF_8));
	}

	/** Every weapon the table names, owned: a melee, ranged and magic bonus each, so that any part finds its first one. */
	private static List<Gear.Stat> everythingNamed() throws Exception
	{
		Set<String> names = new LinkedHashSet<>();
		try (BufferedReader in = reader("/com/caplanner/gear/fights.tsv"))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				String[] c = line.split("\t", -1);
				if (line.startsWith("#") || c.length < 8)
				{
					continue;
				}
				for (String n : c[7].split(";"))
				{
					if (!n.trim().isEmpty())
					{
						names.add(n.trim());
					}
				}
			}
		}
		List<Gear.Stat> out = new ArrayList<>();
		int id = 900000;
		for (String n : names)
		{
			Gear.Stat s = new Gear.Stat();
			s.itemId = id++;
			s.name = n;
			s.slot = 3;
			s.stab = s.slash = s.crush = s.ranged = s.magic = 20;
			s.strength = 20;
			s.speed = 5;
			out.add(s);
		}
		// and a set of each style the sums know, so that the set worn is found
		int[][] real = {{4151, 3, 82, 82, 0, 0, 0}, {12954, 5, 24, 6, 0, 0, 0}, {20997, 3, 0, 0, 70, 0, 20}, {11212, 13, 0, 0, 0, 0, 60},
			{1405, 3, 0, 0, 0, 14, 0}};
		String[] realNames = {"Abyssal whip", "Dragon defender", "Twisted bow", "Dragon arrow", "Mystic air staff"};
		for (int i = 0; i < real.length; i++)
		{
			Gear.Stat s = new Gear.Stat();
			s.itemId = real[i][0];
			s.slot = real[i][1];
			s.name = realNames[i];
			s.slash = real[i][2];
			s.strength = real[i][3];
			s.ranged = real[i][4];
			s.magic = real[i][5];
			s.rangedStrength = real[i][6];
			s.twoHanded = s.itemId == 20997;
			s.speed = s.slot == 3 ? 4 : 0;
			out.add(s);
		}
		return out;
	}

	@Test
	public void noPartBreaksTheRuleOfATask() throws Exception
	{
		Gear gear = new Gear();
		Fights fights;
		try (BufferedReader in = reader("/com/caplanner/gear/fights.tsv"))
		{
			fights = Fights.read(in);
		}
		Rules rules;
		try (BufferedReader in = reader("/com/caplanner/rules.tsv"))
		{
			rules = Rules.read(in);
		}
		Gear.Levels levels = new Gear.Levels();
		levels.attack = levels.strength = levels.ranged = levels.magic = levels.prayer = levels.hitpoints = 99;
		levels.piety = levels.rigour = levels.augury = true;
		List<Gear.Stat> owned = everythingNamed();
		int tasks = 0;
		int checked = 0;
		try (BufferedReader in = reader("/com/caplanner/tasks.tsv"))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				String[] c = line.split("\t");
				if (c.length < 2 || !c[0].matches("\\d+"))
				{
					continue;
				}
				tasks++;
				Gear.Limits limits = GearCard.limitsOf(rules, Integer.parseInt(c[0]));
				if (limits == null || !fights.has(c[1]))
				{
					continue;
				}
				Fights.Plan plan = fights.plan(gear, c[1], owned, levels, false, limits);
				if (plan == null)
				{
					continue;
				}
				checked++;
				for (Fights.Role role : plan.roles)
				{
					for (Gear.Stat s : role.carried)
					{
						String n = s.name.toLowerCase(Locale.ROOT);
						String where = "task " + c[0] + " (" + c[1] + "), part " + role.label + ": " + s.name;
						assertTrue(where + " is excluded", limits.exclude.stream().noneMatch(n::contains));
						if (s.slot == 3 && !limits.weapon.isEmpty())
						{
							assertTrue(where + " is not a weapon the task allows", limits.weapon.stream().anyMatch(n::contains));
						}
					}
				}
			}
		}
		assertTrue(tasks >= 600);
		assertTrue("tasks with a rule in a fight of parts: " + checked, checked >= 8);
	}

	@Test
	public void noSpecialAttackThatLowersDefenceWhereNoneLands() throws Exception
	{
		try (BufferedReader in = reader("/com/caplanner/gear/fights.tsv"))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				String[] c = line.split("\t", -1);
				if (line.startsWith("#") || c.length < 8 || !UNDRAINED.contains(c[0]))
				{
					continue;
				}
				for (String n : c[7].toLowerCase(Locale.ROOT).split(";"))
				{
					assertFalse(c[0] + ": " + n, DRAINS.contains(n.trim()));
				}
			}
		}
	}
}

package com.caplanner.gear;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.caplanner.core.Bag;
import com.caplanner.core.GearView;
import com.caplanner.core.Requirements;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

/** Fights of several parts: the set is for the first, and pieces are carried for the others. */
public class FightsTest
{
	private static final int NECK = 2;
	private static final int WEAPON = 3;
	private static final int BODY = 4;
	private static final int SHIELD = 5;
	private static final int AMMO = 13;

	private static Gear.Stat item(int id, String name, int slot)
	{
		Gear.Stat s = new Gear.Stat();
		s.itemId = id;
		s.name = name;
		s.slot = slot;
		return s;
	}

	private static Gear.Levels maxed()
	{
		Gear.Levels l = new Gear.Levels();
		l.attack = l.strength = l.ranged = l.magic = l.prayer = l.hitpoints = 99;
		l.piety = l.rigour = l.augury = true;
		return l;
	}

	/** A melee, a ranged and a magic weapon, each with a piece or two of its own. */
	private static List<Gear.Stat> threeStyles()
	{
		Gear.Stat whip = item(4151, "Abyssal whip", WEAPON);
		whip.slash = 82;
		whip.strength = 82;
		whip.speed = 4;
		Gear.Stat defender = item(12954, "Dragon defender", SHIELD);
		defender.slash = 24;
		defender.strength = 6;
		Gear.Stat torture = item(19553, "Amulet of torture", NECK);
		torture.slash = 15;
		torture.strength = 10;
		Gear.Stat bow = item(20997, "Twisted bow", WEAPON);
		bow.twoHanded = true;
		bow.ranged = 70;
		bow.rangedStrength = 20;
		bow.speed = 5;
		Gear.Stat arrows = item(11212, "Dragon arrow", AMMO);
		arrows.rangedStrength = 60;
		Gear.Stat anguish = item(19547, "Necklace of anguish", NECK);
		anguish.ranged = 15;
		anguish.rangedStrength = 5;
		Gear.Stat blessing = item(20220, "Holy blessing", AMMO);
		Gear.Stat staff = item(1405, "Mystic air staff", WEAPON);
		staff.magic = 14;
		staff.speed = 5;
		Gear.Stat occult = item(12002, "Occult necklace", NECK);
		occult.magic = 12;
		occult.magicDamage = 5;
		Gear.Stat robe = item(21021, "Ancestral robe top", BODY);
		robe.magic = 35;
		robe.magicDamage = 3;
		return Arrays.asList(whip, defender, torture, bow, arrows, anguish, blessing, staff, occult, robe);
	}

	private static Fights bundled() throws Exception
	{
		try (BufferedReader in = reader("/com/caplanner/gear/fights.tsv"))
		{
			return Fights.read(in);
		}
	}

	private static List<String> names(List<Gear.Stat> items)
	{
		List<String> out = new ArrayList<>();
		for (Gear.Stat s : items)
		{
			out.add(s.name);
		}
		return out;
	}

	@Test
	public void theSetIsForTheFirstPartAndPiecesAreCarriedForTheOthers() throws Exception
	{
		Gear gear = new Gear();
		Fights fights = bundled();
		Fights.Plan plan = fights.plan(gear, "Dagannoth Rex", threeStyles(), maxed(), false, null);
		// one row of pieces a part as a rule, two against the clock
		for (Fights.Role role : plan.roles)
		{
			assertTrue(role.carried.size() <= 4);
		}
		for (Fights.Role role : fights.plan(gear, "Dagannoth Rex", threeStyles(), maxed(), false, null, Fights.MOST_CARRIED_FOR_SPEED).roles)
		{
			assertTrue(role.carried.size() <= 8);
		}
		assertNotNull(plan);
		assertEquals("Magic", plan.main.style);
		assertEquals("Dagannoth Rex", plan.mainLabel);
		assertEquals("Mystic air staff", plan.main.items.get(WEAPON).name);
		// the other two kings, and the special attack of the wiki's tribrid equipment
		assertEquals(3, plan.roles.size());
		assertEquals("Special attack", plan.roles.get(2).label);
		Fights.Role prime = plan.roles.get(0);
		assertEquals("Dagannoth Prime", prime.label);
		assertEquals("Ranged", prime.style);
		// the weapon first, then its ammunition; a blessing is never carried
		assertEquals(Arrays.asList("Twisted bow", "Dragon arrow", "Necklace of anguish"), names(prime.carried));
		assertTrue(prime.dps > 1);
		Fights.Role supreme = plan.roles.get(1);
		assertEquals("Melee", supreme.style);
		assertEquals(Arrays.asList("Abyssal whip", "Dragon defender", "Amulet of torture"), names(supreme.carried));
		// each king's own page wears the set for that king
		assertEquals("Ranged", fights.plan(gear, "Dagannoth Prime", threeStyles(), maxed(), false, null).main.style);
		assertEquals("Melee", fights.plan(gear, "Dagannoth Supreme", threeStyles(), maxed(), false, null).main.style);
		// with one style owned the others are said to be missing, not made up
		Fights.Plan onlyMelee = fights.plan(gear, "Dagannoth Supreme", threeStyles().subList(0, 3), maxed(), false, null);
		assertEquals("Melee", onlyMelee.main.style);
		assertTrue(onlyMelee.roles.get(0).nothing || onlyMelee.roles.get(0).carried.isEmpty());
		assertNull("a boss the table does not have", fights.plan(gear, "Zalcano", threeStyles(), maxed(), false, null));
		assertFalse(fights.has("Zalcano"));
	}

	@Test
	public void aPartThatAsksForAStyleGetsThatStyleAndATaskStillHolds() throws Exception
	{
		Gear gear = new Gear();
		Fights fights = bundled();
		// the totems of the Nightmare are for magic, whatever else would do more
		Fights.Plan nightmare = fights.plan(gear, "The Nightmare", threeStyles(), maxed(), false, null);
		assertEquals("Melee", nightmare.main.style);
		assertEquals("Magic", nightmare.roles.get(0).style);
		assertEquals("Mystic air staff", nightmare.roles.get(0).carried.get(0).name);
		assertNotNull(nightmare.roles.get(0).spell);
		// a task that allows melee only leaves the other parts with nothing, rather than breaking its rule
		Gear.Limits melee = new Gear.Limits();
		melee.styles.add("melee");
		Fights.Plan held = fights.plan(gear, "The Nightmare", threeStyles(), maxed(), false, melee);
		assertTrue(held.roles.get(0).nothing);
		// elementals want a spell that is cast: a staff with an attack of its own is not it
		Gear.Stat shadow = item(27275, "Tumeken's shadow", WEAPON);
		shadow.twoHanded = true;
		shadow.magic = 35;
		shadow.speed = 5;
		List<Gear.Stat> owned = new ArrayList<>(threeStyles());
		owned.add(shadow);
		Fights.Plan titans = fights.plan(gear, "Royal Titans", owned, maxed(), false, null);
		Fights.Role elementals = titans.roles.get(1);
		assertEquals("Mystic air staff", elementals.carried.get(0).name);
		assertEquals("no figure where the sums do not know the part", 0, elementals.dps, 0);
		assertEquals(1, elementals.carried.size());
	}

	@Test
	public void theBundledTableIsSound() throws Exception
	{
		Gear gear = new Gear();
		Fights fights = bundled();
		Set<String> known = new HashSet<>();
		try (BufferedReader in = reader("/com/caplanner/bosses.txt"))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				known.add(Requirements.key(line));
			}
		}
		assertTrue(fights.bosses().size() >= 10);
		for (String boss : fights.bosses())
		{
			assertTrue("not a Combat Achievements boss: " + boss, known.contains(boss));
		}
		for (int id : fights.npcIds())
		{
			assertTrue("no monster of id " + id, gear.hasMonster(id));
		}
		// a boss whose first line is not its main part is left out
		assertFalse(Fights.read(new StringReader("X\tswitch\t2265\tA\t\t\n")).has("X"));
		assertTrue(Fights.read(new StringReader("# c\nX\tmain\t2265\tA\t\t\nbad\n")).has("x"));
	}

	@Test
	public void piecesToChangeIntoSitInRowsOfTheirOwnBeforeTheSupplies()
	{
		List<Bag.Line> six = new ArrayList<>();
		for (int i = 0; i < 6; i++)
		{
			six.add(Bag.Line.worn(100 + i, "piece " + i, true, ""));
		}
		List<Bag.Line> two = Arrays.asList(Bag.Line.worn(200, "a", true, ""), Bag.Line.worn(201, "b", true, ""));
		GearView view = GearView.ready(new HashMap<>(), new HashMap<>(), "Melee", 1, 1).withParts("First",
			Arrays.asList(new GearView.Part("Second", "Ranged", 5, six, null, "", false),
				new GearView.Part("Third", "Magic", 5, two, null, "", false),
				new GearView.Part("Fourth", "", 0, new ArrayList<Bag.Line>(), null, "", true)), new ArrayList<Bag.Line>());
		List<Bag.Line> slots = view.carriedSlots();
		// more than four: down two rows a column at a time (first on top, second under it, third beside the first)
		assertEquals(100, slots.get(0).itemId);
		assertEquals(101, slots.get(4).itemId);
		assertEquals(102, slots.get(1).itemId);
		assertEquals(103, slots.get(5).itemId);
		assertEquals(104, slots.get(2).itemId);
		assertEquals(105, slots.get(6).itemId);
		assertNull(slots.get(3));
		assertNull(slots.get(7));
		// four or fewer: one row, and nothing trails after the last piece
		assertEquals(200, slots.get(8).itemId);
		assertEquals(201, slots.get(9).itemId);
		assertEquals(10, slots.size());
		List<int[]> inventory = view.inventory();
		assertEquals(10, inventory.size());
		assertEquals(0, inventory.get(3)[0]);
		assertEquals(105, inventory.get(6)[0]);
		assertEquals("First", view.wornFor);
		// small parts share a row when the whole part fits: one, then two, then two more start the next row
		List<Bag.Line> one = Arrays.asList(Bag.Line.worn(300, "spec", true, ""));
		List<Bag.Line> three = Arrays.asList(Bag.Line.worn(400, "c", true, ""), Bag.Line.worn(401, "d", true, ""),
			Bag.Line.worn(402, "e", true, ""));
		GearView shared = GearView.ready(new HashMap<>(), new HashMap<>(), "Melee", 1, 1).withParts("",
			Arrays.asList(new GearView.Part("A", "Melee", 0, one, null, "", false), new GearView.Part("B", "Magic", 5, two, null, "", false),
				new GearView.Part("C", "Ranged", 5, three, null, "", false)), new ArrayList<Bag.Line>());
		List<Bag.Line> packed = shared.carriedSlots();
		assertEquals(300, packed.get(0).itemId);
		assertEquals(200, packed.get(1).itemId);
		assertEquals(201, packed.get(2).itemId);
		assertNull("three do not fit in the one slot left: a row of their own", packed.get(3));
		assertEquals(400, packed.get(4).itemId);
		assertEquals(7, packed.size());
	}

